GRID_SIZE = 4
MAX_COLORS_FOUND = 0
BEST_CONFIGURATION = None

def is_valid_coloring(grid):
    """Checks if the 4x4 grid coloring is valid."""
    N = 4
    for i in range(N - 1):
        for j in range(N - 1):
            colors = [grid[i][j], grid[i+1][j], grid[i][j+1], grid[i+1][j+1]]
            if len(set(colors)) == 4:
                return False
    return True

def count_unique_colors(grid):
    """Counts the total number of unique colors used in the grid."""
    colors = set()
    for row in grid:
        for color in row:
            colors.add(color)
    return len(colors)

def solve_recursive(grid, cell_index):
    global MAX_COLORS_FOUND, BEST_CONFIGURATION

    if cell_index == GRID_SIZE * GRID_SIZE:
        # Base case: Grid is fully colored
        if is_valid_coloring(grid):
            k = count_unique_colors(grid)
            if k > MAX_COLORS_FOUND:
                MAX_COLORS_FOUND = k
                BEST_CONFIGURATION = [row[:] for row in grid]
        return

    r, c = divmod(cell_index, GRID_SIZE)

    # Determine the maximum color index already used + 1
    current_max_color = 0
    for i in range(r):
        for j in range(GRID_SIZE):
            if grid[i][j] > current_max_color:
                current_max_color = grid[i][j]
    for j in range(c):
        if grid[r][j] > current_max_color:
            current_max_color = grid[r][j]

    # Try colors from 1 up to (current_max_color + 1). 
    # We allow one new color at each step to maximize k.
    # We cap the search depth in terms of color usage to prevent runaway search.
    # Let's try up to 9 colors globally, hoping the search terminates before hitting 60s limit.
    # If current_max_color + 2 > 9, we cap it at 9.

    max_try_color = min(current_max_color + 2, 9) 

    for color in range(1, max_try_color + 1):
        grid[r][c] = color

        # Local validity check (Pruning)
        is_locally_valid = True
        if r >= 1 and c >= 1:
            subgrid_colors = [
                grid[r-1][c-1], grid[r][c-1], 
                grid[r-1][c], grid[r][c]
            ]
            if len(set(subgrid_colors)) == 4:
                is_locally_valid = False

        if is_locally_valid:
            solve_recursive(grid, cell_index + 1)

        # Backtrack (Crucial)
        grid[r][c] = 0 

# Initialize the grid with 0 (uncolored)
initial_grid = [[0] * GRID_SIZE for _ in range(GRID_SIZE)]

print("Starting comprehensive search for maximum k...")
solve_recursive(initial_grid, 0)

print(f"\n--- Final Results ---")
print(f"Maximum number of colors found (k): {MAX_COLORS_FOUND}")
if BEST_CONFIGURATION:
    print("Corresponding configuration (Colors 1 to k):")
    for row in BEST_CONFIGURATION:
        print(*(row))
else:
    print("No valid configuration found within search constraints.")

