def check_validity(grid):
    R = len(grid)
    C = len(grid[0])
    for i in range(R - 1):
        for j in range(C - 1):
            subgrid = [
                grid[i][j], grid[i][j+1],
                grid[i+1][j], grid[i+1][j+1]
            ]
            distinct_colors = set(subgrid)
            if len(distinct_colors) > 3:
                return False
    return True

def test_pattern(grid):
    is_valid = check_validity(grid)

    all_colors = set()
    for row in grid:
        for color in row:
            all_colors.add(color)

    return is_valid, len(all_colors)

